update public.seo_landing_pages set content=jsonb_set(content, '{en}', '{"title": "Private Tours from Batumi", "seo_title": "Private Tours from Batumi", "description": "Explore Adjara’s waterfalls, mountain villages and Black Sea coast on a private day trip from Batumi.", "body": "Explore Adjara’s waterfalls, mountain villages and Black Sea coast on a private day trip from Batumi. Choose cultural stops, canyon visits or scenic mountain roads depending on your interests and available time. Tell us your accommodation, group size and dates so we can suggest a route and confirm the price. Pickup and seasonal access are confirmed before departure.", "faq": []}'::jsonb), updated_at=now() where slug='tours-from-batumi' and not published and (not (content ? 'en') OR content->'en' = '{}'::jsonb OR content->'en' = '{"title": "Private Tours from Batumi", "body": "Explore Adjara’s waterfalls, mountain villages and Black Sea landscapes on a private trip from Batumi. Choose a route that suits your group and ask about pickup, travel time and seasonal road conditions.", "description": "Explore Adjara’s waterfalls, mountain villages and Black Sea landscapes on a private trip from Batumi. Choose a route that suits your group and ask about p", "seo_title": "Private Tours from Batumi", "faq": []}'::jsonb);
update public.seo_landing_pages set content=jsonb_set(content, '{ka}', '{"title": "კერძო ტურები ბათუმიდან", "seo_title": "კერძო ტურები ბათუმიდან", "description": "აღმოაჩინეთ აჭარის ჩანჩქერები, მთის სოფლები და შავი ზღვის სანაპირო ბათუმიდან კერძო ტურით.", "body": "აღმოაჩინეთ აჭარის ჩანჩქერები, მთის სოფლები და შავი ზღვის სანაპირო ბათუმიდან კერძო ტურით. თქვენი ინტერესებისა და დროის მიხედვით შეარჩიეთ კულტურული ძეგლები, კანიონები ან მთის გზები. გაგვიზიარეთ თარიღები, მგზავრების რაოდენობა და სასტუმროს მისამართი მარშრუტისა და ფასის დასაზუსტებლად.", "faq": []}'::jsonb), updated_at=now() where slug='tours-from-batumi' and not published and (not (content ? 'ka') OR content->'ka' = '{}'::jsonb);
update public.seo_landing_pages set content=jsonb_set(content, '{ru}', '{"title": "Индивидуальные туры из Батуми", "seo_title": "Индивидуальные туры из Батуми", "description": "Откройте водопады Аджарии, горные сёла и побережье Чёрного моря в частной поездке из Батуми.", "body": "Откройте водопады Аджарии, горные сёла и побережье Чёрного моря в частной поездке из Батуми. Выберите культурные достопримечательности, каньоны или горные маршруты. Сообщите даты, адрес отеля и число пассажиров для согласования маршрута и стоимости.", "faq": []}'::jsonb), updated_at=now() where slug='tours-from-batumi' and not published and (not (content ? 'ru') OR content->'ru' = '{}'::jsonb);
update public.seo_landing_pages set content=jsonb_set(content, '{he}', '{"title": "טיולים פרטיים מבאטומי", "seo_title": "טיולים פרטיים מבאטומי", "description": "גלו את מפלי אג׳רה, כפרי ההרים וחוף הים השחור בטיול פרטי מבאטומי.", "body": "גלו את מפלי אג׳רה, כפרי ההרים וחוף הים השחור בטיול פרטי מבאטומי. בחרו אתרי תרבות, קניונים או דרכי נוף לפי תחומי העניין שלכם. שלחו תאריכים, כתובת המלון ומספר נוסעים לתיאום המסלול והמחיר.", "faq": []}'::jsonb), updated_at=now() where slug='tours-from-batumi' and not published and (not (content ? 'he') OR content->'he' = '{}'::jsonb);
update public.seo_landing_pages set content=jsonb_set(content, '{en}', '{"title": "Private Tours from Tbilisi", "seo_title": "Private Tours from Tbilisi", "description": "Discover Kazbegi, Kakheti and historic towns on a private journey from Tbilisi.", "body": "Discover Kazbegi, Kakheti and historic towns on a private journey from Tbilisi. Choose mountain scenery, cultural heritage or wine-country stops. A day trip or longer itinerary can be discussed according to driving time and your interests. Share your pickup address and travel dates to confirm availability and costs.", "faq": []}'::jsonb), updated_at=now() where slug='tours-from-tbilisi' and not published and (not (content ? 'en') OR content->'en' = '{}'::jsonb OR content->'en' = '{"title": "Private Tours from Tbilisi", "body": "Plan a private journey from Tbilisi to Kazbegi, Kakheti or historic towns. Tell us your dates, interests and preferred pace so we can confirm a suitable itinerary and pickup.", "description": "Plan a private journey from Tbilisi to Kazbegi, Kakheti or historic towns. Tell us your dates, interests and preferred pace so we can confirm a suitable it", "seo_title": "Private Tours from Tbilisi", "faq": []}'::jsonb);
update public.seo_landing_pages set content=jsonb_set(content, '{ka}', '{"title": "კერძო ტურები თბილისიდან", "seo_title": "კერძო ტურები თბილისიდან", "description": "აღმოაჩინეთ ყაზბეგი, კახეთი და ისტორიული ქალაქები თბილისიდან კერძო ტურით.", "body": "აღმოაჩინეთ ყაზბეგი, კახეთი და ისტორიული ქალაქები თბილისიდან კერძო ტურით. შეარჩიეთ მთის ხედები, კულტურული ძეგლები ან ღვინის რეგიონის მონახულება. მარშრუტის, ფასისა და ხელმისაწვდომობის დასაზუსტებლად მოგვწერეთ თარიღები და აყვანის მისამართი.", "faq": []}'::jsonb), updated_at=now() where slug='tours-from-tbilisi' and not published and (not (content ? 'ka') OR content->'ka' = '{}'::jsonb);
update public.seo_landing_pages set content=jsonb_set(content, '{ru}', '{"title": "Индивидуальные туры из Тбилиси", "seo_title": "Индивидуальные туры из Тбилиси", "description": "Посетите Казбеги, Кахетию и исторические города в частной поездке из Тбилиси.", "body": "Посетите Казбеги, Кахетию и исторические города в частной поездке из Тбилиси. Выберите горные пейзажи, культурные памятники или винный регион. Сообщите даты и адрес подачи автомобиля для согласования маршрута и стоимости.", "faq": []}'::jsonb), updated_at=now() where slug='tours-from-tbilisi' and not published and (not (content ? 'ru') OR content->'ru' = '{}'::jsonb);
update public.seo_landing_pages set content=jsonb_set(content, '{he}', '{"title": "טיולים פרטיים מטביליסי", "seo_title": "טיולים פרטיים מטביליסי", "description": "גלו את קזבגי, קאחתי וערים היסטוריות בטיול פרטי מטביליסי.", "body": "גלו את קזבגי, קאחתי וערים היסטוריות בטיול פרטי מטביליסי. בחרו נופי הרים, אתרי מורשת או ביקור באזור היין. שלחו תאריכים וכתובת איסוף לתיאום המסלול והמחיר.", "faq": []}'::jsonb), updated_at=now() where slug='tours-from-tbilisi' and not published and (not (content ? 'he') OR content->'he' = '{}'::jsonb);
update public.seo_landing_pages set content=jsonb_set(content, '{en}', '{"title": "Private Transfers in Georgia", "seo_title": "Private Transfers in Georgia", "description": "Arrange a private airport or intercity transfer across Georgia.", "body": "Arrange a private airport or intercity transfer across Georgia. Share your pickup address, destination, arrival time, passenger count and luggage requirements. We will confirm a suitable vehicle, route and price. For mountain destinations, ask about seasonal road conditions and vehicle suitability before booking.", "faq": []}'::jsonb), updated_at=now() where slug='private-transfers' and not published and (not (content ? 'en') OR content->'en' = '{}'::jsonb OR content->'en' = '{"title": "Private Transfers in Georgia", "body": "Arrange airport or intercity transport with a private driver. Share your pickup location, destination, passenger count and luggage requirements for a vehicle and price quote.", "description": "Arrange airport or intercity transport with a private driver. Share your pickup location, destination, passenger count and luggage requirements for a vehic", "seo_title": "Private Transfers in Georgia", "faq": []}'::jsonb);
update public.seo_landing_pages set content=jsonb_set(content, '{ka}', '{"title": "კერძო ტრანსფერები საქართველოში", "seo_title": "კერძო ტრანსფერები საქართველოში", "description": "დაგეგმეთ კერძო ტრანსფერი აეროპორტიდან ან საქართველოს ქალაქებს შორის.", "body": "დაგეგმეთ კერძო ტრანსფერი აეროპორტიდან ან საქართველოს ქალაქებს შორის. მოგვაწოდეთ აყვანის მისამართი, დანიშნულება, დრო, მგზავრებისა და ბარგის რაოდენობა. დავაზუსტებთ ავტომობილს, მარშრუტსა და ფასს.", "faq": []}'::jsonb), updated_at=now() where slug='private-transfers' and not published and (not (content ? 'ka') OR content->'ka' = '{}'::jsonb);
update public.seo_landing_pages set content=jsonb_set(content, '{ru}', '{"title": "Частные трансферы по Грузии", "seo_title": "Частные трансферы по Грузии", "description": "Закажите частный трансфер из аэропорта или между городами Грузии.", "body": "Закажите частный трансфер из аэропорта или между городами Грузии. Укажите адрес подачи, пункт назначения, время, число пассажиров и багаж. Мы согласуем автомобиль, маршрут и цену с учётом дорожных условий.", "faq": []}'::jsonb), updated_at=now() where slug='private-transfers' and not published and (not (content ? 'ru') OR content->'ru' = '{}'::jsonb);
update public.seo_landing_pages set content=jsonb_set(content, '{he}', '{"title": "הסעות פרטיות בגאורגיה", "seo_title": "הסעות פרטיות בגאורגיה", "description": "תאמו הסעה פרטית משדה התעופה או בין ערים בגאורגיה.", "body": "תאמו הסעה פרטית משדה התעופה או בין ערים בגאורגיה. ציינו כתובת איסוף, יעד, שעה, מספר נוסעים וכמות מזוודות. נתאם רכב מתאים, מסלול ומחיר בהתאם לתנאי הדרך.", "faq": []}'::jsonb), updated_at=now() where slug='private-transfers' and not published and (not (content ? 'he') OR content->'he' = '{}'::jsonb);
update public.seo_landing_pages set content=jsonb_set(content, '{en}', '{"title": "Multi-Day Tours in Georgia", "seo_title": "Multi-Day Tours in Georgia", "description": "Combine Svaneti, mountain valleys, historic sites and the Black Sea coast in a private multi-day itinerary.", "body": "Combine Svaneti, mountain valleys, historic sites and the Black Sea coast in a private multi-day itinerary. Plan overnight stops and realistic driving times rather than rushing between destinations. Tell us your starting city, number of days and interests; ask about hotel assistance and what is included in your quote.", "faq": []}'::jsonb), updated_at=now() where slug='multi-day-tours' and not published and (not (content ? 'en') OR content->'en' = '{}'::jsonb OR content->'en' = '{"title": "Multi-Day Tours in Georgia", "body": "Explore several regions on one private itinerary. Combine mountain scenery, cultural stops and coastal destinations; discuss overnight stops, driving times and hotel assistance before booking.", "description": "Explore several regions on one private itinerary. Combine mountain scenery, cultural stops and coastal destinations; discuss overnight stops, driving times", "seo_title": "Multi-Day Tours in Georgia", "faq": []}'::jsonb);
update public.seo_landing_pages set content=jsonb_set(content, '{ka}', '{"title": "მრავალდღიანი ტურები საქართველოში", "seo_title": "მრავალდღიანი ტურები საქართველოში", "description": "გააერთიანეთ სვანეთი, მთის ხეობები, ისტორიული ძეგლები და შავი ზღვის სანაპირო მრავალდღიან კერძო ტურში.", "body": "გააერთიანეთ სვანეთი, მთის ხეობები, ისტორიული ძეგლები და შავი ზღვის სანაპირო მრავალდღიან კერძო ტურში. წინასწარ დაგეგმეთ ღამისთევა და მგზავრობის დრო. მოგვწერეთ საწყისი ქალაქი, დღეების რაოდენობა და ინტერესები.", "faq": []}'::jsonb), updated_at=now() where slug='multi-day-tours' and not published and (not (content ? 'ka') OR content->'ka' = '{}'::jsonb);
update public.seo_landing_pages set content=jsonb_set(content, '{ru}', '{"title": "Многодневные туры по Грузии", "seo_title": "Многодневные туры по Грузии", "description": "Объедините Сванетию, горные долины, исторические места и побережье в индивидуальном многодневном маршруте.", "body": "Объедините Сванетию, горные долины, исторические места и побережье в индивидуальном многодневном маршруте. Заранее обсудите ночёвки и время в дороге. Сообщите город старта, число дней и интересы, уточните помощь с отелями.", "faq": []}'::jsonb), updated_at=now() where slug='multi-day-tours' and not published and (not (content ? 'ru') OR content->'ru' = '{}'::jsonb);
update public.seo_landing_pages set content=jsonb_set(content, '{he}', '{"title": "טיולים בני מספר ימים בגאורגיה", "seo_title": "טיולים בני מספר ימים בגאורגיה", "description": "שלבו את סוואנתי, עמקי ההרים, אתרים היסטוריים וחוף הים במסלול פרטי של מספר ימים.", "body": "שלבו את סוואנתי, עמקי ההרים, אתרים היסטוריים וחוף הים במסלול פרטי של מספר ימים. תכננו לינות וזמני נסיעה מראש. ציינו עיר מוצא, מספר ימים ותחומי עניין ושאלו על סיוע במלונות.", "faq": []}'::jsonb), updated_at=now() where slug='multi-day-tours' and not published and (not (content ? 'he') OR content->'he' = '{}'::jsonb);
update public.seo_landing_pages set content=jsonb_set(content, '{en}', '{"title": "Winter Tours in Georgia", "seo_title": "Winter Tours in Georgia", "description": "Explore snowy landscapes around Goderdzi, Gudauri or Bakuriani on a private winter trip.", "body": "Explore snowy landscapes around Goderdzi, Gudauri or Bakuriani on a private winter trip. Options depend on the starting city, weather, road restrictions and suitable vehicles. Discuss your dates, preferred activities and overnight stops in advance; snow and access cannot be guaranteed.", "faq": []}'::jsonb), updated_at=now() where slug='winter-tours' and not published and (not (content ? 'en') OR content->'en' = '{}'::jsonb OR content->'en' = '{"title": "Winter Tours in Georgia", "body": "Plan a winter journey to Goderdzi, Gudauri or Bakuriani. Snow and road restrictions can affect access, so confirm your dates, vehicle requirements and itinerary before departure.", "description": "Plan a winter journey to Goderdzi, Gudauri or Bakuriani. Snow and road restrictions can affect access, so confirm your dates, vehicle requirements and itin", "seo_title": "Winter Tours in Georgia", "faq": []}'::jsonb);
update public.seo_landing_pages set content=jsonb_set(content, '{ka}', '{"title": "ზამთრის ტურები საქართველოში", "seo_title": "ზამთრის ტურები საქართველოში", "description": "აღმოაჩინეთ გოდერძის, გუდაურისა და ბაკურიანის თოვლიანი ხედები კერძო ზამთრის ტურით.", "body": "აღმოაჩინეთ გოდერძის, გუდაურისა და ბაკურიანის თოვლიანი ხედები კერძო ზამთრის ტურით. მარშრუტი დამოკიდებულია ამინდზე, გზის მდგომარეობასა და ავტომობილზე. წინასწარ შეათანხმეთ თარიღები, აქტივობები და ღამისთევა.", "faq": []}'::jsonb), updated_at=now() where slug='winter-tours' and not published and (not (content ? 'ka') OR content->'ka' = '{}'::jsonb);
update public.seo_landing_pages set content=jsonb_set(content, '{ru}', '{"title": "Зимние туры по Грузии", "seo_title": "Зимние туры по Грузии", "description": "Откройте снежные пейзажи Годердзи, Гудаури или Бакуриани в частной зимней поездке.", "body": "Откройте снежные пейзажи Годердзи, Гудаури или Бакуриани в частной зимней поездке. Маршрут зависит от погоды, состояния дорог и подходящего автомобиля. Заранее согласуйте даты, занятия и ночёвки; доступ не гарантирован.", "faq": []}'::jsonb), updated_at=now() where slug='winter-tours' and not published and (not (content ? 'ru') OR content->'ru' = '{}'::jsonb);
update public.seo_landing_pages set content=jsonb_set(content, '{he}', '{"title": "טיולי חורף בגאורגיה", "seo_title": "טיולי חורף בגאורגיה", "description": "גלו נופים מושלגים בגודרדזי, גודאורי או בקוריאני בטיול חורף פרטי.", "body": "גלו נופים מושלגים בגודרדזי, גודאורי או בקוריאני בטיול חורף פרטי. המסלול תלוי במזג האוויר, במצב הכבישים וברכב מתאים. תאמו מראש תאריכים, פעילויות ולינות; אין הבטחה לגישה או לשלג.", "faq": []}'::jsonb), updated_at=now() where slug='winter-tours' and not published and (not (content ? 'he') OR content->'he' = '{}'::jsonb);
update public.seo_landing_pages set content=jsonb_set(content, '{en}', '{"title": "4×4 Adventure Tours in Georgia", "seo_title": "4×4 Adventure Tours in Georgia", "description": "Discover mountain valleys, remote villages and scenic roads with a suitable private vehicle.", "body": "Discover mountain valleys, remote villages and scenic roads with a suitable private vehicle. Explore possible routes in Adjara or Svaneti based on the season and road conditions. Share your group size, destinations and travel dates so we can confirm vehicle suitability and a realistic itinerary. Access to remote trails is not guaranteed.", "faq": []}'::jsonb), updated_at=now() where slug='4x4-adventure-tours' and not published and (not (content ? 'en') OR content->'en' = '{}'::jsonb OR content->'en' = '{"title": "4×4 Adventure Tours in Georgia", "body": "Discover mountain roads and scenic valleys with a suitable private vehicle. Tell us your group size and preferred destinations; routes depend on weather, road access and vehicle availability.", "description": "Discover mountain roads and scenic valleys with a suitable private vehicle. Tell us your group size and preferred destinations; routes depend on weather, r", "seo_title": "4×4 Adventure Tours in Georgia", "faq": []}'::jsonb);
update public.seo_landing_pages set content=jsonb_set(content, '{ka}', '{"title": "4×4 სათავგადასავლო ტურები საქართველოში", "seo_title": "4×4 სათავგადასავლო ტურები საქართველოში", "description": "აღმოაჩინეთ მთის ხეობები, შორეული სოფლები და თვალწარმტაცი გზები შესაფერისი ავტომობილით.", "body": "აღმოაჩინეთ მთის ხეობები, შორეული სოფლები და თვალწარმტაცი გზები შესაფერისი ავტომობილით. აჭარისა და სვანეთის მარშრუტები დამოკიდებულია სეზონსა და გზის მდგომარეობაზე. მოგვწერეთ თარიღები და ჯგუფის ზომა მარშრუტის დასაზუსტებლად.", "faq": []}'::jsonb), updated_at=now() where slug='4x4-adventure-tours' and not published and (not (content ? 'ka') OR content->'ka' = '{}'::jsonb);
update public.seo_landing_pages set content=jsonb_set(content, '{ru}', '{"title": "Туры на 4×4 по Грузии", "seo_title": "Туры на 4×4 по Грузии", "description": "Откройте горные долины, удалённые сёла и живописные дороги на подходящем автомобиле.", "body": "Откройте горные долины, удалённые сёла и живописные дороги на подходящем автомобиле. Маршруты Аджарии и Сванетии зависят от сезона и состояния дорог. Сообщите даты и размер группы для согласования поездки.", "faq": []}'::jsonb), updated_at=now() where slug='4x4-adventure-tours' and not published and (not (content ? 'ru') OR content->'ru' = '{}'::jsonb);
update public.seo_landing_pages set content=jsonb_set(content, '{he}', '{"title": "טיולי 4×4 בגאורגיה", "seo_title": "טיולי 4×4 בגאורגיה", "description": "גלו עמקי הרים, כפרים מרוחקים ודרכי נוף ברכב מתאים.", "body": "גלו עמקי הרים, כפרים מרוחקים ודרכי נוף ברכב מתאים. המסלולים באג׳רה ובסוואנתי תלויים בעונה ובמצב הדרכים. ציינו תאריכים וגודל קבוצה לתיאום רכב ומסלול אפשרי.", "faq": []}'::jsonb), updated_at=now() where slug='4x4-adventure-tours' and not published and (not (content ? 'he') OR content->'he' = '{}'::jsonb);
